package com.littlemakers.village.nativeapp;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** Shared native HUD. Art uses cached paths/shaders; only interaction animates these controls. */
final class GameUi {
 static void control(Button b,ThemeManager t){String label=b.getText().toString();boolean icon=label.equals("Home")||label.length()<=2;b.setElevation(0);b.setStateListAnimator(null);b.setTypeface(t.font(true));b.setTextColor(t.text);b.setTextSize(icon?23:16);b.setMinHeight(t.dp(64));GradientDrawable shape=new GradientDrawable();shape.setColor(icon?t.surface:t.accent);shape.setCornerRadius(t.dp(icon?32:16));b.setBackground(shape);if(label.equals("Home")){b.setText("⌂");b.setContentDescription("Home");}ThemeManager.bindPress(b);}
 static void primary(Button b,ThemeManager t){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xff167b80,0xff086168});d.setCornerRadius(t.dp(18));b.setBackground(d);b.setTextColor(Color.WHITE);}
 static TextView label(Context c,ThemeManager t,String value,int sp,boolean bold){TextView v=new TextView(c);v.setText(value);v.setTextSize(sp);v.setTextColor(t.text);v.setTypeface(t.font(bold));return v;}
 static LinearLayout balance(Context c,ThemeManager t,int stars,int coins){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER);String[]labels={"★  "+stars,"●  "+coins};for(int i=0;i<2;i++){TextView v=label(c,t,labels[i],16,true);v.setGravity(Gravity.CENTER);v.setPadding(t.dp(18),t.dp(8),t.dp(18),t.dp(8));GradientDrawable d=new GradientDrawable();d.setColor(i==0?t.gold:t.mint);d.setCornerRadius(t.dp(24));v.setBackground(d);v.setContentDescription((i==0?stars+" stars":coins+" coins"));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(t.dp(4),0,t.dp(4),0);row.addView(v,p);}return row;}
 static LinearLayout grid(Context c){LinearLayout g=new LinearLayout(c);g.setOrientation(LinearLayout.VERTICAL);return g;}
 static void cells(LinearLayout grid,View[]items,int columns,ThemeManager t,int minHeight){for(int first=0;first<items.length;first+=columns){LinearLayout row=new LinearLayout(grid.getContext());for(int col=0;col<columns;col++){int i=first+col;View v=i<items.length?items[i]:new View(grid.getContext());v.setMinimumHeight(t.dp(minHeight));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);lp.setMargins(t.dp(4),t.dp(4),t.dp(4),t.dp(4));row.addView(v,lp);}grid.addView(row,new LinearLayout.LayoutParams(-1,-2));}}
 static View card(Context c,ThemeManager t,String title,String detail,int art,int color,boolean wide,boolean selected,Runnable task){LinearLayout tile=new LinearLayout(c);tile.setOrientation(wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);tile.setGravity(wide?Gravity.CENTER_VERTICAL:Gravity.CENTER);tile.setPadding(t.dp(12),t.dp(10),t.dp(12),t.dp(10));GradientDrawable bg=new GradientDrawable();bg.setColor(selected?t.accent:t.surface);bg.setCornerRadius(t.dp(20));if(selected)bg.setStroke(t.dp(2),t.dark?0xff64d7cd:0xff147d79);tile.setBackground(bg);Illustration picture=new Illustration(c,art,color);picture.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);tile.addView(picture,new LinearLayout.LayoutParams(t.dp(wide?78:60),t.dp(wide?78:58)));LinearLayout copy=new LinearLayout(c);copy.setOrientation(1);copy.setGravity(wide?Gravity.CENTER_VERTICAL:Gravity.CENTER);TextView name=label(c,t,title,wide?18:14,true);name.setGravity(wide?Gravity.START:Gravity.CENTER);copy.addView(name);TextView sub=label(c,t,detail,wide?14:12,false);sub.setPadding(0,t.dp(4),0,0);sub.setGravity(wide?Gravity.START:Gravity.CENTER);copy.addView(sub);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(wide?0:-1,-2,wide?1:0);cp.leftMargin=wide?t.dp(12):0;tile.addView(copy,cp);tile.setMinimumHeight(t.dp(wide?108:112));tile.setFocusable(true);tile.setContentDescription(title+", "+detail);for(int i=0;i<copy.getChildCount();i++)copy.getChildAt(i).setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);tile.setOnClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);task.run();});ThemeManager.bindPress(tile);return tile;}
 /** Original toy thumbnails; no bitmap decoding, blur filters, shadow layers or idle loops. */
 static final class Illustration extends View {
  final Paint p=new Paint(3);final Path shape=new Path();final int art,color;final Shader shine;
  Illustration(Context c,int art,int color){super(c);this.art=art;this.color=color;shine=new RadialGradient(36,26,52,new int[]{mix(color,Color.WHITE,.6f),color,mix(color,Color.BLACK,.18f)},new float[]{0,.55f,1},Shader.TileMode.CLAMP);}
  static int mix(int a,int b,float f){return Color.rgb((int)(Color.red(a)*(1-f)+Color.red(b)*f),(int)(Color.green(a)*(1-f)+Color.green(b)*f),(int)(Color.blue(a)*(1-f)+Color.blue(b)*f));}
  void fill(int col){p.setShader(null);p.setColor(col);p.setStyle(Paint.Style.FILL);}void oval(Canvas c,float l,float t,float r,float b,int col){fill(col);c.drawOval(l,t,r,b,p);}void line(Canvas c,float x,float y,float xx,float yy,int col,float w){fill(col);p.setStrokeWidth(w);p.setStrokeCap(Paint.Cap.ROUND);c.drawLine(x,y,xx,yy,p);}
  @Override protected void onDraw(Canvas c){c.save();float scale=Math.min(getWidth(),getHeight())/100f;c.translate((getWidth()-scale*100)/2,(getHeight()-scale*100)/2);c.scale(scale,scale);oval(c,17,82,85,92,0x19314e5b);
   if(art<=3){p.setColor(Color.WHITE);p.setShader(shine);c.drawOval(22,12,79,80,p);p.setShader(null);oval(c,9,49,31,63,color);oval(c,72,49,94,63,color);oval(c,25,76,47,87,color);oval(c,57,76,79,87,color);oval(c,37,39,44,48,0xff173c46);oval(c,59,39,66,48,0xff173c46);oval(c,38,39,40,41,Color.WHITE);oval(c,60,39,62,41,Color.WHITE);fill(0xff173c46);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);c.drawArc(44,51,59,62,8,164,false,p);p.setStyle(Paint.Style.FILL);
    if(art==1){fill(0xffdfb37c);c.drawRoundRect(27,5,74,28,7,7,p);c.drawRoundRect(17,22,83,30,4,4,p);}if(art==2){fill(0xffdc91b0);shape.reset();shape.moveTo(45,15);shape.lineTo(25,3);shape.lineTo(25,27);shape.lineTo(45,15);shape.lineTo(63,3);shape.lineTo(63,27);shape.close();c.drawPath(shape,p);}if(art==3)star(c,72,65,12,0xfff2c862);
   }else if(art==10||art==14){for(int i=0;i<3;i++){line(c,48,83,25+i*23,22+(i%2)*13,color,7);oval(c,18+i*23,17+(i%2)*13,33+i*23,47+(i%2)*13,color);} }
   else if(art==11){p.setColor(Color.WHITE);p.setShader(shine);c.drawOval(15,38,75,83,p);c.drawOval(54,60,91,87,p);p.setShader(null);}
   else if(art==12){line(c,20,82,20,36,color,12);line(c,80,82,80,36,color,12);fill(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(14);c.drawArc(20,10,80,64,180,180,false,p);p.setStyle(Paint.Style.FILL);}
   else if(art==13){for(int i=0;i<5;i++)oval(c,15+i*12,27+(i%2)*5,43+i*12,82,color);}
   else if(art==15){fill(0xffb78b56);c.drawRoundRect(13,35,87,83,8,8,p);fill(0xffe0b96d);c.drawRoundRect(12,24,88,43,8,8,p);line(c,34,28,34,80,0xfff0d88d,5);line(c,67,28,67,80,0xfff0d88d,5);star(c,51,55,9,0xffffe9ad);}
   else if(art==20){oval(c,19,24,78,75,0xff6db8a0);oval(c,68,44,96,67,0xffa8d9ad);oval(c,27,67,44,82,0xffa8d9ad);oval(c,53,67,70,82,0xffa8d9ad);oval(c,83,48,87,53,0xff173c46);}
   else if(art==21){p.setColor(Color.WHITE);p.setShader(shine);c.drawOval(17,24,82,73,p);p.setShader(null);fill(color);shape.reset();shape.moveTo(24,48);shape.lineTo(3,25);shape.lineTo(3,72);shape.close();c.drawPath(shape,p);oval(c,65,39,72,47,0xff173c46);}
   else if(art==22){fill(color);c.drawRoundRect(16,14,84,85,9,9,p);fill(0xffffedcb);c.drawRoundRect(23,20,78,78,5,5,p);line(c,50,21,50,76,color,4);star(c,66,45,12,0xffebbf60);}
   else {star(c,50,48,34,color);}c.restore();
  }
  void star(Canvas c,float x,float y,float r,int col){fill(col);shape.reset();for(int i=0;i<10;i++){double a=-Math.PI/2+i*Math.PI/5;float rr=i%2==0?r:r*.46f;float px=x+(float)Math.cos(a)*rr,py=y+(float)Math.sin(a)*rr;if(i==0)shape.moveTo(px,py);else shape.lineTo(px,py);}shape.close();c.drawPath(shape,p);}
 }
}
